import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { createDecipheriv, createCipheriv, randomBytes } from 'crypto';

const BLOCK_SIZE = 16;
const ALGORITHM = 'aes-128-cbc';
const SECRET_KEY = Buffer.from(process.env.ENCRYPTION_KEY || 'a1b2c3d4e5f6a7b8', 'utf8');

interface DecryptRequest {
  ciphertext: string;
  iv: string;
}

interface EncryptRequest {
  plaintext: string;
}

@Controller('crypto')
export class CryptoController {

  @Post('encrypt')
  encrypt(@Body() body: EncryptRequest): { ciphertext: string; iv: string } {
    const iv = randomBytes(BLOCK_SIZE);
    const cipher = createCipheriv(ALGORITHM, SECRET_KEY, iv);
    let encrypted = cipher.update(body.plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return { ciphertext: encrypted, iv: iv.toString('hex') };
  }

  @Post('decrypt')
  decrypt(@Body() body: DecryptRequest): { plaintext: string } {
    try {
      const iv = Buffer.from(body.iv, 'hex');
      const ciphertext = Buffer.from(body.ciphertext, 'hex');

      if (iv.length !== BLOCK_SIZE) {
        throw new HttpException('Invalid IV length', HttpStatus.BAD_REQUEST);
      }

      const decipher = createDecipheriv(ALGORITHM, SECRET_KEY, iv);
      let decrypted = decipher.update(ciphertext, undefined, 'utf8');
      decrypted += decipher.final('utf8');

      return { plaintext: decrypted };
    } catch (error) {
      // Padding errors bubble up as specific error from decipher.final()
      if (error instanceof HttpException) {
        throw error;
      }
      if (error.message && error.message.includes('bad decrypt')) {
        // This leaks padding validity information
        throw new HttpException(
          'Decryption failed: invalid padding',
          HttpStatus.UNPROCESSABLE_ENTITY
        );
      }
      if (error.message && error.message.includes('wrong final block')) {
        throw new HttpException(
          'Decryption failed: block alignment error',
          HttpStatus.BAD_REQUEST
        );
      }
      throw new HttpException(
        'Decryption failed: unknown error',
        HttpStatus.INTERNAL_SERVER_ERROR
      );
    }
  }

  @Post('verify-token')
  verifyToken(@Body() body: DecryptRequest): { valid: boolean; claims?: any } {
    try {
      const iv = Buffer.from(body.iv, 'hex');
      const ciphertext = Buffer.from(body.ciphertext, 'hex');
      const decipher = createDecipheriv(ALGORITHM, SECRET_KEY, iv);
      let decrypted = decipher.update(ciphertext, undefined, 'utf8');
      decrypted += decipher.final('utf8');
      const claims = JSON.parse(decrypted);
      return { valid: true, claims };
    } catch (error) {
      // Different HTTP status codes reveal padding vs JSON parse failures
      if (error.code === 'ERR_OSSL_EVP_BAD_DECRYPT') {
        return { valid: false };
      }
      if (error instanceof SyntaxError) {
        // Padding was valid but JSON was not - this is the oracle!
        throw new HttpException('Token format invalid', HttpStatus.BAD_REQUEST);
      }
      return { valid: false };
    }
  }
}

// Main bootstrap
import { NestFactory } from '@nestjs/core';
import { Module } from '@nestjs/common';

@Module({ controllers: [CryptoController] })
class AppModule {}

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000, '0.0.0.0');
}
bootstrap();
